      load_pending_reg <= 1'b0;
    end
    if (activate_pending && !peer_fault_active && !fault_reg)
    begin
      load_pending_reg <= 1'b0;
    end
  end
end

always @(posedge clock 1RESET_EDGE)
begin
  if (1RESET_VALUE)
  begin
    load_pending_valid_reg <= 1'b0;
  end
  else
  begin
    if (cfg_pipe_valid_reg)
    begin
      if (!cfg_pipe_legal_reg || cfg_pipe_size_reg != DATA_BITS || cfg_pipe_conflict_reg)
      begin
      end
      else
      begin
        if (!fault_reg && !peer_fault_active &&
        !cfg_pending_reg &&
        (!region_active_reg || drain_complete))
        begin
          load_pending_valid_reg <= 1'b0;
        end
      end
    end
    if (!peer_fault_active && start && in1 == OP_LOAD && !load_pending_reg)
    begin
      if (!load_request_valid)
      begin
      end
      else
      begin
        if (fifo_count_reg == 0)
        begin
          load_pending_valid_reg <= load_request_valid;
        end
      end
    end
    if (fifo_load_done && !peer_fault_active)
    begin
      load_pending_valid_reg <= 1'b0;
    end
    if (activate_pending && !peer_fault_active && !fault_reg)
    begin
      load_pending_valid_reg <= 1'b0;
    end
  end
end

always @(posedge clock 1RESET_EDGE)
begin
  if (1RESET_VALUE)
  begin
    loads_exhausted_reg <= 1'b0;
