      if (!cfg_pipe_legal_reg || cfg_pipe_size_reg != DATA_BITS || cfg_pipe_conflict_reg)
      begin
      end
      else
      begin
        if (!fault_reg && !peer_fault_active &&
        !cfg_pending_reg &&
        (!region_active_reg || drain_complete))
        begin
          loads_exhausted_reg <= (cfg_pipe_count_reg == 0);
        end
      end
    end
    if (fifo_load_done && !peer_fault_active)
    begin
      if (consumed_reg + 1'b1 == region_count_reg)
      begin
        loads_exhausted_reg <= 1'b1;
      end
    end
    if (activate_pending && !peer_fault_active && !fault_reg)
    begin
      loads_exhausted_reg <= (pending_count_reg == 0);
    end
  end
end

