// Every error is sticky until reset. Parallel event detection avoids a
// priority mux chain on the fault register and its dependent control paths.
always @(posedge clock 1RESET_EDGE)
begin
  if (1RESET_VALUE)
  begin
    fault_reg <= 1'b0;
  end
  else
  begin
    if (peer_fault_active ||
    (cfg_pipe_valid_reg && (!cfg_pipe_legal_reg || cfg_pipe_size_reg != DATA_BITS || cfg_pipe_conflict_reg)) ||
    (!peer_fault_active && start && in1 == OP_LOAD && !load_pending_reg && !load_request_valid) ||
    r_fault_event || (start && in1 == OP_STORE))
    begin
      fault_reg <= 1'b1;
    end
  end
end

