localparam integer ADDR_BITS = BITSIZE_m_axi_awaddr;
localparam integer DATA_BITS = BITSIZE_m_axi_wdata;
localparam integer BEAT_BYTES = DATA_BITS / 8;
localparam integer BEAT_SHIFT = $clog2(BEAT_BYTES);
localparam integer COUNT_BITS = BITSIZE_in5;
localparam integer COUNT_W = COUNT_BITS - 1;
localparam integer OFFSET_W = (ADDR_BITS > COUNT_W ? ADDR_BITS : COUNT_W);
localparam integer PTR_W = (FIFO_DEPTH <= 2) ? 1 : $clog2(FIFO_DEPTH);
localparam integer FIFO_COUNT_W = $clog2(FIFO_DEPTH + 1);
localparam integer LEN_W = (B_MAX < 1) ? 1 : $clog2(B_MAX + 1);
localparam integer END_BEAT_W = ((ADDR_BITS - BEAT_SHIFT) > COUNT_BITS ?
    (ADDR_BITS - BEAT_SHIFT) : COUNT_BITS) + 1;
localparam integer BOUNDARY_BEATS = 4096 / BEAT_BYTES;
localparam integer BOUNDARY_W = $clog2(BOUNDARY_BEATS) + 1;
localparam integer OP_STORE = 1;
localparam integer OP_CONFIGURE = 2;
localparam integer OP_DRAIN = 3;

reg done_reg;
assign done = done_reg;

reg fault_reg;
reg region_active_reg;
reg [ADDR_BITS-1:0] region_base_reg;
reg [COUNT_W-1:0] region_count_reg;
reg [ADDR_BITS-1:0] next_expected_address_reg;
reg stores_exhausted_reg;
// The payload pipeline register has to survive synthesis: folding it into the
// distributed-RAM write port would put the kernel payload cone straight back onto the
// FIFO write path, which is what this fast mode exists to avoid. DONT_TOUCH keeps it, and
// the register plus its attribute exist only when FAST_STORE_ACK is set, so the
// FAST_STORE_ACK=0 flow keeps exactly its original structure. FAST_STORE_ACK defaults
// to 1 and the generated kernels always pass 1: the fast acknowledgement has no
// compiler switch anymore. Value 0 is only reachable from the RTL qualification
// harness, which instantiates the engine directly.
wire fast_pipe_valid;
wire [BITSIZE_in3-1:0] fast_pipe_data;
