reg [COUNT_W-1:0] scheduled_reg;
reg [COUNT_W-1:0] remaining_beats_reg;
reg remaining_has_high_reg;
reg [COUNT_W-1:0] plan_scheduled_reg;
reg [LEN_W-1:0] plan_beats_reg [0:1];
reg [ADDR_BITS-1:0] plan_address_reg [0:1];
reg plan_rd_ptr_reg;
reg plan_wr_ptr_reg;
reg [1:0] plan_count_reg;
reg [COUNT_W-1:0] completed_reg;
reg cfg_seen_reg;
reg store_seen_reg;
reg drain_seen_reg;
reg drain_pending_reg;
reg store_pending_reg;
reg store_ack_reg;
reg store_ack_pending_reg;
reg [BITSIZE_in2-1:0] store_ack_size_reg;
reg [BITSIZE_in3-1:0] store_ack_data_reg;
reg [ADDR_BITS-1:0] store_ack_address_reg;
reg [BITSIZE_in2-1:0] pending_size_reg;
reg [BITSIZE_in3-1:0] pending_data_reg;
reg [ADDR_BITS-1:0] pending_address_reg;
reg [BITSIZE_in2-1:0] cfg_size_reg;
reg [ADDR_BITS-1:0] cfg_base_reg;
reg [COUNT_BITS-1:0] cfg_count_reg;
reg cfg_pipe_valid_reg;
reg cfg_pipe_legal_reg;
reg cfg_pipe_idle_reg;
reg [BITSIZE_in2-1:0] cfg_pipe_size_reg;
reg [ADDR_BITS-1:0] cfg_pipe_base_reg;
reg [COUNT_BITS-1:0] cfg_pipe_count_reg;
reg configure_ack_reg;
reg [BITSIZE_in2-1:0] store_size_reg;
reg [BITSIZE_in3-1:0] store_data_reg;
reg [ADDR_BITS-1:0] store_address_reg;
// The clamp only keeps the derived widths well-formed. The elaboration-time check below
// rejects MAX_OUTSTANDING outside [1,16] in simulation and in synthesis alike, so no
// out-of-range value reaches the descriptor ring: this is a defensive width, not a policy
// that silently accepts a wrong parameter.
localparam integer DESC_DEPTH = (MAX_OUTSTANDING < 1) ? 1 : MAX_OUTSTANDING;
localparam integer DESC_PTR_W = (DESC_DEPTH <= 2) ? 1 : $clog2(DESC_DEPTH);
localparam integer DESC_COUNT_W = (DESC_DEPTH <= 1) ? 1 : $clog2(DESC_DEPTH + 1);
localparam integer RESERVED_COUNT_W = $clog2(DESC_DEPTH * B_MAX + 1);
localparam integer STORE_ADDR_CHUNK_BITS = 8;
localparam [FIFO_COUNT_W-1:0] FIFO_SLOT_LIMIT = FIFO_DEPTH;
localparam integer STORE_ADDR_CHUNK_COUNT = (ADDR_BITS + STORE_ADDR_CHUNK_BITS - 1) /
    STORE_ADDR_CHUNK_BITS;
reg [ADDR_BITS-1:0] descriptor_address_reg [0:DESC_DEPTH-1];
reg [LEN_W-1:0] descriptor_beats_reg [0:DESC_DEPTH-1];
reg [LEN_W-1:0] descriptor_w_remaining_reg [0:DESC_DEPTH-1];
reg descriptor_valid_reg [0:DESC_DEPTH-1];
reg descriptor_aw_done_reg [0:DESC_DEPTH-1];
reg [DESC_PTR_W-1:0] descriptor_alloc_ptr_reg;
reg [DESC_PTR_W-1:0] descriptor_aw_ptr_reg;
reg [DESC_PTR_W-1:0] descriptor_w_ptr_reg;
reg [DESC_PTR_W-1:0] descriptor_b_ptr_reg;
reg [DESC_COUNT_W-1:0] descriptor_count_reg;
reg [RESERVED_COUNT_W-1:0] reserved_data_count_reg;
reg [BITSIZE_in3-1:0] fifo_reg [0:FIFO_DEPTH-1];
reg [PTR_W-1:0] fifo_rd_ptr_reg;
reg [PTR_W-1:0] fifo_wr_ptr_reg;
reg [FIFO_COUNT_W-1:0] fifo_count_reg;
wire [END_BEAT_W-1:0] region_end;
reg [LEN_W-1:0] burst_limit;
reg [LEN_W-1:0] plan_limit;
reg [BOUNDARY_W-1:0] boundary_beats_reg;
reg boundary_within_burst_reg;
