genvar store_address_chunk;
generate
  for (store_address_chunk = 0; store_address_chunk < STORE_ADDR_CHUNK_COUNT;
  store_address_chunk = store_address_chunk + 1)
  begin: store_address_chunks
    localparam integer CHUNK_LSB = store_address_chunk * STORE_ADDR_CHUNK_BITS;
    localparam integer CHUNK_WIDTH = (ADDR_BITS - CHUNK_LSB < STORE_ADDR_CHUNK_BITS) ?
        ADDR_BITS - CHUNK_LSB : STORE_ADDR_CHUNK_BITS;
    wire chunk_carry_in;
    wire [CHUNK_WIDTH:0] chunk_sum;

    if (store_address_chunk == 0)
    begin: first_chunk
      assign chunk_carry_in = 1'b0;
    end
    else
    begin: later_chunk
      assign chunk_carry_in = in4[CHUNK_LSB] ^ region_base_reg[CHUNK_LSB] ^
          accepted_offset[CHUNK_LSB];
    end

    assign chunk_sum = {1'b0, region_base_reg[CHUNK_LSB +: CHUNK_WIDTH]} +
        {1'b0, accepted_offset[CHUNK_LSB +: CHUNK_WIDTH]} +
        chunk_carry_in;

    if (CHUNK_LSB + CHUNK_WIDTH < ADDR_BITS)
    begin: nonfinal_chunk
      assign store_address_chunk_valid[store_address_chunk] =
          (chunk_sum[CHUNK_WIDTH-1:0] == in4[CHUNK_LSB +: CHUNK_WIDTH]) &&
          (chunk_sum[CHUNK_WIDTH] ==
          (in4[CHUNK_LSB + CHUNK_WIDTH] ^ region_base_reg[CHUNK_LSB + CHUNK_WIDTH] ^
          accepted_offset[CHUNK_LSB + CHUNK_WIDTH]));
    end
    else
    begin: final_chunk
      assign store_address_chunk_valid[store_address_chunk] =
          chunk_sum[CHUNK_WIDTH-1:0] == in4[CHUNK_LSB +: CHUNK_WIDTH];
      assign store_address_final_carry = chunk_sum[CHUNK_WIDTH];
    end
  end
endgenerate
generate
