    ((FAST_STORE_ACK != 0) ? !fast_pipe_valid : 1'b1);
assign store_enqueue = !fault_reg && !peer_fault_active &&
    ((FAST_STORE_ACK != 0) ? pending_store_enqueue :
    ((direct_store && store_request_valid && (fifo_count_reg < FIFO_DEPTH)) ||
