// Parameter legality is checked at elaboration time, where synthesis can see it too: an
// out-of-range parameter stops the build instead of being clamped or silently accepted.
// Vivado reports the message (Synth 8-6058); Verilator reports it as USERFATAL, which the
// regression harness promotes to an error with -Werror-USERFATAL.
generate
  if (!(B_MAX >= 1 && B_MAX <= 256))
  begin : PARAM_CHECK_B_MAX
    $fatal(1, "B_MAX must be in [1,256]");
  end
  if (!(MAX_OUTSTANDING >= 1 && MAX_OUTSTANDING <= 16))
  begin : PARAM_CHECK_MAX_OUTSTANDING
    $fatal(1, "MAX_OUTSTANDING must be in [1,16]");
  end
  if (!(FIFO_DEPTH >= B_MAX && FIFO_DEPTH <= 4096 &&
  (FIFO_DEPTH & (FIFO_DEPTH - 1)) == 0))
  begin : PARAM_CHECK_FIFO_DEPTH
    $fatal(1, "FIFO_DEPTH must be a power of two >= B_MAX and <= 4096");
  end
  if (DATA_BITS != 32)
  begin : PARAM_CHECK_DATA_BITS
    $fatal(1, "F1 writer supports 32-bit data beats only");
  end
  if (ADDR_BITS < 12)
  begin : PARAM_CHECK_ADDR_BITS
    $fatal(1, "address width must be at least 12 bits for the 4 KiB rule");
  end
endgenerate

