        reserve_beats = 0;
        plan_limit = B_MAX;
        if (boundary_within_burst_reg && boundary_beats_reg[LEN_W-1:0] < plan_limit)
            plan_limit = boundary_beats_reg;
        if (!remaining_has_high_reg && remaining_beats_reg[LEN_W-1:0] < plan_limit)
            plan_limit = remaining_beats_reg[LEN_W-1:0];
        burst_limit = B_MAX;
        if (plan_count_reg != 0)
