    if (cfg_pipe_valid_reg)
    begin
      if (!cfg_pipe_legal_reg || cfg_pipe_size_reg != DATA_BITS || !cfg_pipe_idle_reg)
      begin
      end
      else
      begin
        if (!fault_reg && !peer_fault_active)
        begin
          reserved_data_count_reg <= 0;
        end
      end
    end
    case ({(reserve_beats != 0), w_push})
      2'b10:
      begin
        reserved_data_count_reg <= reserved_data_count_reg + reserve_beats;
      end
      2'b01:
      begin
        reserved_data_count_reg <= reserved_data_count_reg - 1'b1;
      end
      2'b11:
      begin
        reserved_data_count_reg <= reserved_data_count_reg + reserve_beats - 1'b1;
      end
      default:
      begin
        reserved_data_count_reg <= reserved_data_count_reg;
      end
    endcase
  end
end

always @(posedge clock 1RESET_EDGE)
begin
  if (1RESET_VALUE)
  begin
    scheduled_reg <= 0;
  end
  else
  begin
    if (cfg_pipe_valid_reg)
    begin
      if (!cfg_pipe_legal_reg || cfg_pipe_size_reg != DATA_BITS || !cfg_pipe_idle_reg)
      begin
      end
      else
      begin
        if (!fault_reg && !peer_fault_active)
        begin
          scheduled_reg <= 0;
        end
      end
    end
    if (reserve_beats != 0)
    begin
      scheduled_reg[LEN_W-1:0] <= scheduled_low_sum[LEN_W-1:0];
      if (scheduled_low_sum[LEN_W])
      begin
        scheduled_reg[COUNT_W-1:LEN_W] <= scheduled_reg[COUNT_W-1:LEN_W] + 1'b1;
      end
    end
  end
end

always @(posedge clock 1RESET_EDGE)
begin
  if (1RESET_VALUE)
  begin
    store_ack_reg <= 1'b0;
  end
  else
  begin
    store_ack_reg <= store_enqueue;
  end
end

always @(posedge clock 1RESET_EDGE)
begin
  if (1RESET_VALUE)
  begin
    store_ack_address_reg <= 0;
  end
  else
  begin
    if (store_enqueue)
    begin
      store_ack_address_reg <= pending_store_enqueue ? pending_address_reg : in4;
    end
  end
end

always @(posedge clock 1RESET_EDGE)
begin
  if (1RESET_VALUE)
  begin
    store_ack_data_reg <= 0;
  end
  else
  begin
    if (store_enqueue)
    begin
      store_ack_data_reg <= pending_store_enqueue ? pending_data_reg : in3;
    end
  end
end

always @(posedge clock 1RESET_EDGE)
begin
  if (1RESET_VALUE)
  begin
    store_ack_pending_reg <= 1'b0;
  end
  else
  begin
    store_ack_pending_reg <= store_enqueue && pending_store_enqueue;
  end
end

always @(posedge clock 1RESET_EDGE)
begin
  if (1RESET_VALUE)
  begin
    store_ack_size_reg <= 0;
  end
  else
  begin
    if (store_enqueue)
    begin
      store_ack_size_reg <= pending_store_enqueue ? pending_size_reg : in2;
    end
  end
end

always @(posedge clock 1RESET_EDGE)
begin
  if (1RESET_VALUE)
  begin
    store_address_reg <= 0;
  end
  else
  begin
    if (!fault_reg && !peer_fault_active && direct_store && !store_pending_reg)
    begin
      store_address_reg <= in4;
    end
  end
end

always @(posedge clock 1RESET_EDGE)
begin
  if (1RESET_VALUE)
  begin
    store_data_reg <= 0;
  end
  else
  begin
    if (!fault_reg && !peer_fault_active && direct_store && !store_pending_reg)
    begin
      store_data_reg <= in3;
    end
  end
end

always @(posedge clock 1RESET_EDGE)
begin
  if (1RESET_VALUE)
  begin
    store_pending_reg <= 1'b0;
  end
  else
  begin
    if (!fault_reg && !peer_fault_active && direct_store && !store_pending_reg)
    begin
      if (!store_request_valid)
      begin
      end
      else
      begin
        if (capture_store_pending)
        begin
          store_pending_reg <= 1'b1;
        end
      end
    end
    else
    begin
      if (store_pending_reg)
      begin
        if (pending_store_enqueue)
        begin
          store_pending_reg <= 1'b0;
        end
      end
    end
  end
end

always @(posedge clock 1RESET_EDGE)
begin
  if (1RESET_VALUE)
  begin
    store_seen_reg <= 1'b0;
  end
  else
  begin
    if (!store_pending_reg)
    begin
      if (!start || (in1 != OP_STORE))
      begin
        store_seen_reg <= 1'b0;
      end
      else
      begin
        if (in2 != store_size_reg || in3 != store_data_reg || in4 != store_address_reg)
        begin
          store_seen_reg <= 1'b0;
        end
      end
    end
    if (!fault_reg && !peer_fault_active && direct_store && !store_pending_reg)
    begin
      store_seen_reg <= 1'b1;
    end
  end
end

always @(posedge clock 1RESET_EDGE)
begin
  if (1RESET_VALUE)
  begin
    store_size_reg <= 0;
  end
  else
  begin
    if (!fault_reg && !peer_fault_active && direct_store && !store_pending_reg)
    begin
      store_size_reg <= in2;
    end
  end
end

always @(posedge clock 1RESET_EDGE)
begin
  if (1RESET_VALUE)
  begin
    if (FAST_STORE_ACK != 0)
    begin
      stores_exhausted_reg <= 1'b0;
    end
  end
  else
  begin
    if (store_enqueue)
    begin
      if (FAST_STORE_ACK != 0)
      begin
        stores_exhausted_reg <= (accepted_reg + 1'b1 == region_count_reg);
      end
    end
    if (cfg_pipe_valid_reg)
    begin
      if (!cfg_pipe_legal_reg || cfg_pipe_size_reg != DATA_BITS || !cfg_pipe_idle_reg)
      begin
      end
      else
      begin
        if (!fault_reg && !peer_fault_active)
        begin
          if (FAST_STORE_ACK != 0)
          begin
            stores_exhausted_reg <= (cfg_pipe_count_reg == 0);
          end
        end
      end
    end
    if (fast_store_accept)
    begin
      stores_exhausted_reg <= (accepted_reg + 1'b1 == region_count_reg);
    end
  end
end



// Every error is sticky until reset. Parallel event detection avoids a
// priority mux chain on the fault register and its dependent control paths.
always @(posedge clock 1RESET_EDGE)
begin
  if (1RESET_VALUE)
  begin
    fault_reg <= 1'b0;
  end
  else
  begin
    if (peer_fault_active ||
    (cfg_pipe_valid_reg && (!cfg_pipe_legal_reg || cfg_pipe_size_reg != DATA_BITS || !cfg_pipe_idle_reg)) ||
    (!fault_reg && !peer_fault_active && direct_store && !store_pending_reg && !store_request_valid) ||
    (store_pending_reg && pending_store_changed) ||
    (!peer_fault_active && !store_pending_reg && !store_ack_pending_reg && start &&
    in1 == OP_DRAIN && !drain_seen_reg && region_active_reg && accepted_reg != region_count_reg) ||
    (b_push && ((|m_axi_bid) || m_axi_bresp != 0)))
    begin
      fault_reg <= 1'b1;
    end
  end
end
